    "<title>Quipus settings saved</title>\n"
    "<style>\n"
    "*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:26px;background:#fff;color:#0e203a;font:15px/1.65 -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}.shell{max-width:440px;width:100%}.brand{margin:0 0 24px;font-weight:750;font-size:21px;letter-spacing:.18em}.panel{position:relative;padding:29px;border:1px solid #dce1e8;box-shadow:0 15px 45px #0e203a0a}.panel::before{content:\"\";position:absolute;right:-1px;top:-1px;width:54px;height:5px;background:#c40000}.check{display:grid;place-items:center;width:42px;height:42px;margin-bottom:18px;border:1px solid #a7cbb6;background:#f0f7f3;color:#187448;font-size:23px}h1{margin:0 0 13px;font-size:27px;line-height:1.2;letter-spacing:-.04em}p{margin:0 0 15px;color:#526174}strong{color:#0e203a}.next{margin:21px 0 0;border-top:1px solid #dce1e8;padding-top:17px;font-size:12px}footer{margin-top:18px;color:#526174;font-size:11px}@media(max-width:360px){body{padding:20px}.panel{padding:23px}}\n"
    "</style>\n"
    "<style>.action{display:block;margin-top:20px;padding:13px 20px;min-height:48px;background:#c40000;color:white;font-weight:650;text-align:center;text-decoration:none}.action:focus-visible{outline:2px solid #0e203a;outline-offset:4px}</style>\n"
    "</head>\n"
    "<body>\n"
    "<main class=\"shell\"><div class=\"brand\">QUIPUS</div><section class=\"panel\" data-return-auto><div class=\"check\" aria-hidden=\"true\">&#10003;</div><h1>Settings saved.</h1><p>Quipus is restarting. <strong>Keep it powered on.</strong></p><p>Check the recorder screen for Wi-Fi and pairing confirmation.</p><p class=\"next\" id=\"return-state\" role=\"status\">Reconnect this phone or laptop to your normal internet. We’ll open your Quipus dashboard when it is reachable.</p><a class=\"action\" data-quipus-dashboard href=\"" LANTERN_API_BASE_URL "/dashboard/devices\" referrerpolicy=\"no-referrer\">Return to Quipus</a></section><footer>Your conversations. Connected.</footer></main>\n"
    "<script>\n"
    "/* Embedded in both setup pages; the destination comes from the firmware API URL. */\n"
    "(function () {\n"
    "  \"use strict\";\n"
    "  var started = false;\n"
    "  window.quipusSetupReturn = function () {\n"
    "    if (started) return;\n"
    "    started = true;\n"
    "    var link = document.querySelector(\"[data-quipus-dashboard]\");\n"
    "    var notice = document.getElementById(\"return-state\");\n"
    "    var destination = new URL(link.href);\n"
    "    var deadline = Date.now() + 120000, timer, image, timeout, finished = false;\n"
    "\n"
    "    function stop() {\n"
    "      finished = true;\n"
    "      clearTimeout(timer); clearTimeout(timeout);\n"
    "      if (image) { image.onload = null; image.onerror = null; }\n"
    "      window.removeEventListener(\"online\", retry);\n"
    "      document.removeEventListener(\"visibilitychange\", retry);\n"
    "    }\n"
    "    function retry() {\n"
    "      if (finished || document.hidden) return;\n"
    "      clearTimeout(timer);\n"
    "      if (image) return;\n"
    "      if (Date.now() >= deadline) {\n"
    "        stop();\n"
    "        notice.textContent = \"After reconnecting this phone or laptop to normal internet, choose Return to Quipus.\";\n"
    "        return;\n"
    "      }\n"
    "      // A new URL prevents a cached image from falsely certifying internet access.\n"
    "      // No Wi-Fi credentials or pairing code are sent to the public website.\n"
    "      image = new Image();\n"
    "      image.referrerPolicy = \"no-referrer\";\n"
    "      function unavailable() {\n"
    "        clearTimeout(timeout);\n"
    "        image.onload = null; image.onerror = null; image = null;\n"
    "        if (!finished) timer = setTimeout(retry, 5000);\n"
    "      }\n"
    "      image.onload = function () {\n"
    "        stop();\n"
    "        notice.textContent = \"Opening your Quipus dashboard…\";\n"
    "        window.location.replace(destination.href);\n"
    "      };\n"
    "      image.onerror = unavailable;\n"
    "      timeout = setTimeout(unavailable, 5000);\n"
    "      image.src = destination.origin + \"/quipus-icon-192.png?setup=\" + Date.now();\n"
    "    }\n"
    "    window.addEventListener(\"online\", retry);\n"
    "    document.addEventListener(\"visibilitychange\", retry);\n"
    "    window.addEventListener(\"pagehide\", stop, { once: true });\n"
    "    timer = setTimeout(retry, 1500);\n"
    "  };\n"
    "  if (document.querySelector(\"[data-return-auto]\")) window.quipusSetupReturn();\n"
    "}());\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";
